fn read(x:&[bool],offset:usize,n:usize)->N{let mut out=N::zero();for i in 0..n{if x[offset+i]{out|=N::one()<<i;}}out}
fn source_values(x:&[bool],d:usize)->Vec<N>{assert!(d>0&&x.len()>=5*d);(0..5).map(|i|read(x,i*d,d)).collect()}
fn replace_sources(x:&[bool],d:usize,values:&[N])->Vec<bool>{assert_eq!(values.len(),5);let mut out=x.to_vec();for(i,value)in values.iter().enumerate(){assert!(value.bits()as usize<=d);for j in 0..d{out[i*d+j]=value.bit(j as u64);}}out}
fn canonical(x:&[bool],d:usize)->Vec<bool>{let mut values=source_values(x,d);values.sort();replace_sources(x,d,&values)}
fn next_permutation(x:&mut[N])->bool{let Some(i)=(0..x.len()-1).rev().find(|i|x[*i]<x[*i+1])else{return false;};let j=(i+1..x.len()).rev().find(|j|x[*j]>x[i]).unwrap();x.swap(i,j);x[i+1..].reverse();true}
fn expand(x:&[bool],d:usize)->Vec<Vec<bool>>{let mut values=source_values(x,d);assert!(values.windows(2).all(|p|p[0]<=p[1]));let mut out=vec![];loop{out.push(replace_sources(x,d,&values));assert!(out.len()<=120);if !next_permutation(&mut values){break;}}out}
fn literal_accepts(m:&Model,d:usize,x:&[bool])->bool{assert_eq!(x.len(),5*d+m.c.n+1);let sources=source_values(x,d);let r=read(x,5*d,m.c.n);let hc=m.c.product(&sources);let(h,k,s,trace)=m.recover(&hc,&r,x[5*d+m.c.n]);trace&&m.c.literal(&h,&k,&r,&s,&m.a,&m.b,&m.z,&m.yt)==hc}
pub fn controls()->Value{let mut cases=vec![];let mut assignments=0;for(n,modulus,d,a,yt)in[(2,7,1,0,0),(2,7,1,0,1),(2,7,1,1,2),(2,7,1,1,3),(3,11,1,0,0),(3,11,1,0,1),(3,11,2,0,0),(3,11,2,0,1)]{let m=Model::new(n,N::from(modulus as u32),N::from(a as u32),N::one(),N::one(),N::from(yt as u32));let primary=5*d+n+1;let mut full=std::collections::BTreeSet::new();for mask in 0..1usize<<primary{let x=(0..primary).map(|i|mask>>i&1!=0).collect::<Vec<_>>();if literal_accepts(&m,d,&x){full.insert(x);}assignments+=1;}let representatives=full.iter().map(|x|canonical(x,d)).collect::<std::collections::BTreeSet<_>>();assert!(representatives.iter().all(|x|full.contains(x)));let mut restored=std::collections::BTreeSet::new();let mut histogram=std::collections::BTreeMap::new();for x in &representatives{let orbit=expand(x,d);*histogram.entry(orbit.len()).or_insert(0usize)+=1;for y in orbit{assert_eq!(canonical(&y,d),*x);assert_eq!(&y[5*d..],&x[5*d..]);assert!(literal_accepts(&m,d,&y));assert!(restored.insert(y));}}assert_eq!(restored,full);cases.push(json!({"n":n,"domain_bits":d,"a":a,"target_y":yt,"ordered_primary_roots":full.len(),"sorted_representatives":representatives.len(),"orbit_size_histogram":histogram}));}let zero=vec![false;8];assert_eq!(expand(&zero,1).len(),1);let mut one=zero.clone();one[4]=true;assert_eq!(expand(&one,1).len(),5);json!({"status":"passed","literal_primary_assignments":assignments,"cases":cases,"uniform_division_by120_refuted":true,"original_root_count_exact":null,"release_gate_claim":false,"scope":"pre-registration exact norm symmetry/restoration oracle only; no comparator/native search or original auxiliary reconstruction"})}
